CREATE DEFINER=`root`@`localhost` FUNCTION `FuzzyMembership`(value DOUBLE, low DOUBLE, high DOUBLE) RETURNS double
    DETERMINISTIC
BEGIN
    IF value <= low THEN
        RETURN 0;
    ELSEIF value >= high THEN
        RETURN 1;
    ELSE
        RETURN (value - low) / (high - low);
    END IF;
END ;;
DELIMITER ;
